const input = $input.first().json;

// n8n Webhook payload is normally inside `body`
const data = input.body ?? input;

const errors = [];

// -------------------------
// Business validation
// -------------------------
if (!data.business?.name?.trim()) {
  errors.push("Business name is required");
}

if (!data.business?.email?.trim()) {
  errors.push("Business email is required");
}

// -------------------------
// Customer validation
// -------------------------
if (!data.customer?.name?.trim()) {
  errors.push("Customer name is required");
}

if (!data.customer?.email?.trim()) {
  errors.push("Customer email is required");
}

// Basic email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (
  data.business?.email &&
  !emailRegex.test(data.business.email)
) {
  errors.push("Business email is invalid");
}

if (
  data.customer?.email &&
  !emailRegex.test(data.customer.email)
) {
  errors.push("Customer email is invalid");
}

// -------------------------
// Invoice validation
// -------------------------
if (!data.invoice?.number?.trim()) {
  errors.push("Invoice number is required");
}

if (!data.invoice?.date) {
  errors.push("Invoice date is required");
}

if (!data.invoice?.currency?.trim()) {
  errors.push("Currency is required");
}

// -------------------------
// Items validation
// -------------------------
if (!Array.isArray(data.items) || data.items.length === 0) {
  errors.push("At least one invoice item is required");
} else {
  data.items.forEach((item, index) => {
    const itemNumber = index + 1;

    if (!item.description?.trim()) {
      errors.push(`Item ${itemNumber}: description is required`);
    }

    if (
      typeof item.quantity !== "number" ||
      !Number.isFinite(item.quantity) ||
      item.quantity <= 0
    ) {
      errors.push(
        `Item ${itemNumber}: quantity must be greater than 0`
      );
    }

    if (
      typeof item.unit_price !== "number" ||
      !Number.isFinite(item.unit_price) ||
      item.unit_price < 0
    ) {
      errors.push(
        `Item ${itemNumber}: unit price cannot be negative`
      );
    }
  });
}

// -------------------------
// Discount validation
// -------------------------
if (data.discount) {
  const discountType = data.discount.type;
  const discountValue = data.discount.value;

  if (!["percentage", "fixed"].includes(discountType)) {
    errors.push(
      "Discount type must be either percentage or fixed"
    );
  }

  if (
    typeof discountValue !== "number" ||
    !Number.isFinite(discountValue) ||
    discountValue < 0
  ) {
    errors.push("Discount value must be 0 or greater");
  }

  if (
    discountType === "percentage" &&
    discountValue > 100
  ) {
    errors.push("Discount percentage cannot exceed 100");
  }
}

// -------------------------
// Tax validation
// -------------------------
if (data.tax) {
  const taxType = data.tax.type;
  const taxValue = data.tax.value;

  if (!["percentage", "fixed"].includes(taxType)) {
    errors.push(
      "Tax type must be either percentage or fixed"
    );
  }

  if (
    typeof taxValue !== "number" ||
    !Number.isFinite(taxValue) ||
    taxValue < 0
  ) {
    errors.push("Tax value must be 0 or greater");
  }

  if (
    taxType === "percentage" &&
    taxValue > 100
  ) {
    errors.push("Tax percentage cannot exceed 100");
  }
}

// -------------------------
// Final response
// -------------------------
if (errors.length > 0) {
  return [
    {
      json: {
        success: false,
        valid: false,
        error: "Invalid invoice data",
        details: errors
      }
    }
  ];
}

// Valid input
return [
  {
    json: {
      success: true,
      valid: true,
      data
    }
  }
];

