// --------------------------------------------------
// Helper: round monetary values to 2 decimal places
// --------------------------------------------------
function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

// --------------------------------------------------
// Calculate line items
// --------------------------------------------------
const calculatedItems = invoice.items.map((item, index) => {
  const quantity = Number(item.quantity);
  const unitPrice = Number(item.unitPrice);

  const lineTotal = roundMoney(quantity * unitPrice);

  return {
    itemNumber: index + 1,
    description: item.description,
    quantity,
    unitPrice,
    lineTotal
  };
});

// --------------------------------------------------
// Subtotal
// --------------------------------------------------
const subtotal = roundMoney(
  calculatedItems.reduce(
    (sum, item) => sum + item.lineTotal,
    0
  )
);

// --------------------------------------------------
// Discount
// --------------------------------------------------
let discountAmount = 0;

if (invoice.discount?.type === "percentage") {
  discountAmount = roundMoney(
    subtotal * (Number(invoice.discount.value) / 100)
  );
}

if (invoice.discount?.type === "fixed") {
  discountAmount = roundMoney(
    Number(invoice.discount.value)
  );
}

// Prevent discount from exceeding subtotal
discountAmount = Math.min(discountAmount, subtotal);

// --------------------------------------------------
// Taxable amount
// --------------------------------------------------
const taxableAmount = roundMoney(
  subtotal - discountAmount
);

// --------------------------------------------------
// Tax
// --------------------------------------------------
let taxAmount = 0;

if (invoice.tax?.type === "percentage") {
  taxAmount = roundMoney(
    taxableAmount * (Number(invoice.tax.value) / 100)
  );
}

if (invoice.tax?.type === "fixed") {
  taxAmount = roundMoney(
    Number(invoice.tax.value)
  );
}

// --------------------------------------------------
// Grand total
// --------------------------------------------------
const grandTotal = roundMoney(
  taxableAmount + taxAmount
);

// --------------------------------------------------
// Final output
// --------------------------------------------------
return [
  {
    json: {
      success: true,

      invoice: {
        ...invoice,

        items: calculatedItems,

        calculations: {
          subtotal,
          discountAmount,
          taxableAmount,
          taxAmount,
          grandTotal,
          amountDue: grandTotal
        }
      }
    }
  }
];

