const items = $input.all();

const now = new Date();

return items.map(item => {
  const invoice = item.json;

  const dueDate = new Date(invoice["Due Date"]);

  let status = String(invoice["Status"] || "pending").toLowerCase();

  let invoiceState = "unknown";
  let action = "none";
  let daysDifference = null;

  // --------------------------------------------
  // Ignore already paid invoices
  // --------------------------------------------
  if (status === "paid") {
    invoiceState = "paid";
    action = "none";
  }

  // --------------------------------------------
  // Check unpaid invoices
  // --------------------------------------------
  else if (status === "pending") {

    // Normalize both dates to midnight
    const today = new Date(now);
    today.setHours(0, 0, 0, 0);

    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);

    const differenceMs = due.getTime() - today.getTime();

    daysDifference = Math.round(
      differenceMs / (1000 * 60 * 60 * 24)
    );

    // ------------------------------------------
    // Upcoming invoice
    // ------------------------------------------
    if (daysDifference > 3) {
      invoiceState = "upcoming";
      action = "none";
    }

    // ------------------------------------------
    // Due within 3 days
    // ------------------------------------------
    else if (daysDifference > 0) {
      invoiceState = "due_soon";
      action = "reminder";
    }

    // ------------------------------------------
    // Due today
    // ------------------------------------------
    else if (daysDifference === 0) {
      invoiceState = "due_today";
      action = "reminder";
    }

    // ------------------------------------------
    // Overdue
    // ------------------------------------------
    else {
      invoiceState = "overdue";
      action = "overdue_reminder";
    }
  }

  return {
    json: {
      ...invoice,

      invoiceState,
      action,
      daysDifference
    }
  };
});

