const items = $input.all();

return items.map(item => {
  const data = item.json.body ?? item.json;

  const invoiceNumber = String(data.invoiceNumber || "").trim();
  const paymentStatus = String(data.paymentStatus || "").trim().toLowerCase();

  if (!invoiceNumber) {
    throw new Error("Invoice number is required");
  }

  if (paymentStatus !== "paid") {
    throw new Error("Payment status must be 'paid'");
  }

  return {
    json: {
      invoiceNumber,
      paymentStatus
    }
  };
});
